package com.aistock.prediction.modelcatalog;
import com.aistock.prediction.question.*;import com.aistock.prediction.analysis.*;import com.aistock.prediction.maas.MaasOperationGate;import com.aistock.common.BusinessException;import java.util.*;import java.time.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static com.aistock.prediction.question.QuestionSamples.*;
@Tag("mysql") class QuestionMysqlTest {
 static final Instant NOW=Instant.parse("2026-10-09T14:00:00Z");
 static UUID seed(ModelDatabaseFixture db,UUID user){var ar=new AnalysisRepository(db.jdbc,M);var in=new AnalysisInput(UUID.randomUUID(),"SH600030",LocalDate.parse("2026-07-07"),LocalDate.parse("2026-10-07"),UUID.randomUUID());ar.claim(user,in,new AnalysisFacts.Facts(Map.of(),analysis(false).path("context"),UUID.randomUUID().toString().replace("-","").repeat(2)),NOW);return UUID.fromString(ar.complete(in.operationId(),M.createArrayNode(),null,NOW).path("analysisId").asText());}
 @Test void replayCacheOwnershipAndFailure(){var db=new ModelDatabaseFixture();var user=UUID.randomUUID();var id=seed(db,user);var source=new AnalysisRepository(db.jdbc,M).get(user,id);var r=new QuestionRepository(db.jdbc,M);var in=new QuestionInput(UUID.randomUUID(),id,"风险？");var f=QuestionFacts.build(source,in.question(),"test",M);assertNull(r.replay(user,in,NOW));assertTrue(r.claim(user,in,f,NOW).execute());assertThrows(BusinessException.class,()->r.replay(UUID.randomUUID(),in,NOW));assertThrows(BusinessException.class,()->r.replay(user,new QuestionInput(in.operationId(),id,"不同问题"),NOW));var answer=QuestionAnswerTemplate.render(raw("RISK","{{BASIS_LIMIT}}。","BASIS_LIMIT"),f.values(),M);var done=r.complete(in.operationId(),answer,null,NOW.plusSeconds(1));assertEquals("SUCCEEDED",done.path("state").asText());assertEquals(1,r.list(user,id,1,NOW).path("total").asInt());assertThrows(BusinessException.class,()->r.get(UUID.randomUUID(),UUID.fromString(done.path("answerId").asText())));assertFalse(r.claim(user,new QuestionInput(UUID.randomUUID(),id,"风险？"),f,NOW.plusSeconds(2)).execute());assertEquals(2,db.jdbc.queryForObject("select count(*) from stock_question_operation",Integer.class));}
 @Test void expiryAndLateResultDoNotTouchNewSlot(){var db=new ModelDatabaseFixture();var user=UUID.randomUUID();var id=seed(db,user);var in=new QuestionInput(UUID.randomUUID(),id,"风险？");var r=new QuestionRepository(db.jdbc,M);r.claim(user,in,QuestionFacts.build(new AnalysisRepository(db.jdbc,M).get(user,id),in.question(),"test",M),NOW);assertTrue(r.operation(user,in.operationId(),NOW.plusSeconds(51)).path("expired").asBoolean());var newer=UUID.randomUUID();new MaasOperationGate(db.jdbc).lockAndAcquire("STOCK_ANALYSIS",newer,NOW.plusSeconds(51));assertEquals("FAILED",r.complete(in.operationId(),null,"AI_UNAVAILABLE",NOW.plusSeconds(52)).path("state").asText());assertEquals(newer.toString(),db.jdbc.queryForObject("select operation_id from prediction_explanation_slot",String.class));assertEquals(0,db.jdbc.queryForObject("select count(*) from stock_question_result",Integer.class));}
 @Test void sameOperationConcurrentClaimHasExactlyOneExecutor()throws Exception{var db=new ModelDatabaseFixture();var user=UUID.randomUUID();var id=seed(db,user);var r=new QuestionRepository(db.jdbc,M);var in=new QuestionInput(UUID.randomUUID(),id,"风险？");var f=QuestionFacts.build(new AnalysisRepository(db.jdbc,M).get(user,id),in.question(),"test",M);var pool=java.util.concurrent.Executors.newFixedThreadPool(2);try(var c=db.jdbc.getDataSource().getConnection()){c.setAutoCommit(false);try(var statement=c.prepareStatement("select * from prediction_explanation_slot where slot_id=1 for update")){statement.executeQuery().close();}var ready=new java.util.concurrent.CountDownLatch(2);var start=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.Callable<QuestionRepository.Claim> work=()->{ready.countDown();start.await();return r.claim(user,in,f,NOW);};var one=pool.submit(work);var two=pool.submit(work);assertTrue(ready.await(3,java.util.concurrent.TimeUnit.SECONDS));start.countDown();Thread.sleep(300);c.commit();var first=one.get(4,java.util.concurrent.TimeUnit.SECONDS);var second=two.get(4,java.util.concurrent.TimeUnit.SECONDS);assertNotEquals(first.execute(),second.execute());assertEquals(1,db.jdbc.queryForObject("select count(*) from stock_question_operation",Integer.class));}finally{pool.shutdownNow();}} @Test void differentSourcesAndFailedRetryDoNotMixWhileCacheIgnoresBusySlot(){var db=new ModelDatabaseFixture();var user=UUID.randomUUID();var first=seed(db,user);var second=seed(db,user);var ar=new AnalysisRepository(db.jdbc,M);var r=new QuestionRepository(db.jdbc,M);var one=new QuestionInput(UUID.randomUUID(),first,"风险？");var f1=QuestionFacts.build(ar.get(user,first),one.question(),"test",M);var f2=QuestionFacts.build(ar.get(user,second),one.question(),"test",M);assertNotEquals(f1.hash(),f2.hash());assertTrue(r.claim(user,one,f1,NOW).execute());assertEquals("FAILED",r.complete(one.operationId(),null,"AI_UNAVAILABLE",NOW).path("state").asText());var retry=new QuestionInput(UUID.randomUUID(),first,"风险？");assertTrue(r.claim(user,retry,f1,NOW).execute());var answer=QuestionAnswerTemplate.render(raw("RISK","{{BASIS_LIMIT}}。","BASIS_LIMIT"),f1.values(),M);var original=r.complete(retry.operationId(),answer,null,NOW);var newer=UUID.randomUUID();new MaasOperationGate(db.jdbc).lockAndAcquire("PREDICTION_EXPLANATION",newer,NOW);var cache=r.claim(user,new QuestionInput(UUID.randomUUID(),first,"风险？"),f1,NOW);assertFalse(cache.execute());assertEquals(original.path("answerId"),cache.receipt().path("answerId"));assertEquals(newer.toString(),db.jdbc.queryForObject("select operation_id from prediction_explanation_slot",String.class));new MaasOperationGate(db.jdbc).release("PREDICTION_EXPLANATION",newer);var other=r.claim(user,new QuestionInput(UUID.randomUUID(),second,"风险？"),f2,NOW);assertTrue(other.execute());assertEquals(second.toString(),other.receipt().path("analysisId").asText());}}
